using System.IO;
using System.Text.Json;
using System.Windows;
using MySqlConnector;
namespace AnoWowItemEditor;
public partial class MainWindow
{
    private async Task VerifySafetyStatsAndBosses(CatalogResult catalog,ReferenceCatalog refs)
    {
        static void Assert(bool value,string message){if(!value)throw new InvalidOperationException(message);}
        var thunder=await ItemEditing.LoadAsync(19019);var initial=thunder.Expected;var unsafeItem=new CatalogItem(new(thunder.Current.Fields,StringComparer.OrdinalIgnoreCase){["ItemLevel"]="101"});var supported=new CatalogItem(new(thunder.Current.Fields,StringComparer.OrdinalIgnoreCase){["ItemLevel"]="100"});Assert(thunder.Calculations.ServerProblems(unsafeItem).Any(p=>p.Contains("ItemDamageOneHand")&&p.Contains("101")),"Missing weapon damage row 101 is identified");Assert(thunder.Calculations.ServerProblems(supported).Count==0&&thunder.Calculations.Evaluate(supported,60).Dps.HasValue,"Level 100 damage is supported by the actual table");Assert(ItemTooltip.Build(unsafeItem,catalog.Tooltips,catalog.Items.ToDictionary(i=>i.Id)).Any(l=>l.Text.Contains("MISSING SERVER DATA")),"Missing table rows have a distinct unsafe tooltip explanation");
        var cloneSource=await ItemCloning.LoadAsync(19019);var nativeHead=catalog.Originals[22418];int strength=Enumerable.Range(1,10).First(n=>nativeHead.Number("StatModifierBonusStat"+n)==4),defense=Enumerable.Range(1,10).First(n=>nativeHead.Number("StatModifierBonusStat"+n)==12);var editor=new ItemEditorWindow(catalog){Owner=this};editor.Show();await editor.SelectAsync(22418);editor.SetDraftValue("StatModifierBonusStat"+strength,"4");editor.SetDraftValue("StatModifierBonusStat"+defense,"12");var computed=catalog.Tooltips.Calculations.Evaluate(editor.Draft,60);editor.EditStatForVerification(strength,5,computed.Stats[strength].ToString());editor.EditStatForVerification(defense,32,computed.Stats[defense].ToString());Assert(editor.Draft.Number("StatModifierBonusStat"+strength)==5&&editor.Draft.Number("StatModifierBonusStat"+defense)==32,"Stat type changes immediately enter draft without an Apply button");editor.SetDraftValue("SubclassID","3");editor.SetDraftValue("AllowableClass","64");Assert(editor.SubclassLabel.Contains("Mail"),"Plate can be changed to named Mail");var edited=editor.Draft;var session=editor.Session!;await RenderEditorWindow(editor,"mail-intellect-crit-draft-preview");editor.ResetDraft();editor.Close();
        var kindFilter=new ItemKindFilter(catalog.Tooltips);kindFilter.ItemClass.SelectedItem=kindFilter.ItemClass.Items.Cast<FilterChoice>().Single(c=>c.Id==4);kindFilter.Subtype.SelectedItem=kindFilter.Subtype.Items.Cast<ItemSubtypeChoice>().Single(c=>c.ClassId==4&&c.SubclassId==3);Assert(kindFilter.Matches(edited)&&!kindFilter.Matches(nativeHead),"Mail filtering distinguishes changed mail from original plate");
        var world=await WorldDropCatalog.LoadAsync();Assert(world.Bosses.Count>0,"Instance encounter data exposes bosses");var boss=world.Bosses.FirstOrDefault(b=>b.CreatureId==11502)??world.Bosses.First(b=>world.Creatures.Count(c=>c.Loot==b.LootId)==1);var bossPlan=BossDrops.Plan(world,thunder.Current,[boss.Key],10m);Assert(bossPlan.Mode=="Boss"&&bossPlan.Targets.Single().Entry==boss.CreatureId,"Instance selection produces only selected boss target");
        using var db=await DatabaseConnection.OpenAsync(CatalogRepository.Database);await ContentEditing.InitializeAsync(db);using(var gate=new MySqlCommand("SELECT GET_LOCK('anocore_studio_forge',8)",db))Assert(Convert.ToInt32(await gate.ExecuteScalarAsync())==1,"Safety/boss verification lock");
        try{using var tx=await db.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);try{
            bool blocked=false;try{await ItemEditing.SaveCoreAsync(db,tx,thunder,unsafeItem);}catch(InvalidOperationException ex)when(ex.Message.Contains("Save blocked")){blocked=true;}Assert(blocked,"Unsafe direct item save is blocked before writes");blocked=false;try{await ItemCloning.SaveCoreAsync(db,tx,cloneSource,unsafeItem);}catch(InvalidOperationException ex)when(ex.Message.Contains("Save blocked")){blocked=true;}Assert(blocked,"Unsafe duplicate save is blocked");
            var badSnapshot=new ItemSnapshot(new(){["item_sparse"]=[unsafeItem.Fields.ToDictionary(p=>p.Key,p=>(string?)p.Value)],["item"]=[]});blocked=false;try{await ItemSaveSafety.ValidateSnapshot(db,tx,badSnapshot,19019);}catch(InvalidOperationException ex)when(ex.Message.Contains("Restoration blocked")){blocked=true;}Assert(blocked,"Archived unsafe snapshots cannot bypass restore validation");
            string edit=await ItemEditing.SaveCoreAsync(db,tx,session,edited);var reread=await ItemEditing.LoadAsync(22418,db,tx);Assert(reread.Current.Number("StatModifierBonusStat"+strength)==5&&reread.Current.Number("StatModifierBonusStat"+defense)==32,"Intellect and crit survive saving and reloading");Assert(reread.Current.Number("SubclassID")==3&&reread.Current.Number("AllowableClass")==64,"Mail and Shaman restriction survive reload");var itemOp=await ContentEditing.ReadAsync(db,tx,edit);await ContentEditing.ToggleCoreAsync(db,tx,itemOp);var inactive=await ContentEditing.ReadAsync(db,tx,edit);await ContentEditing.ToggleCoreAsync(db,tx,inactive);
            var copy=await ItemCloning.SaveCoreAsync(db,tx,cloneSource,new(new(thunder.Current.Fields,StringComparer.OrdinalIgnoreCase){["Display"]="Boss drop verification copy"}));var newItem=(await ItemEditing.LoadAsync(copy.Id,db,tx)).Current;var expected=await ItemDropEditing.Capture(db,tx,copy.Id);string dropId=await ItemDropEditing.SaveCore(db,tx,newItem,expected,bossPlan);var dropOp=await ContentEditing.ReadAsync(db,tx,dropId);var assigned=await ItemDropEditing.Capture(db,tx,copy.Id);Assert(assigned.Tables["world_loot"].Count==1&&assigned.Tables["world_loot"].Single()["Entry"]==boss.LootId.ToString()&&assigned.Tables["world_loot"].Single()["Chance"]=="10","Only selected boss loot table receives the copy at chosen chance");await ContentEditing.ToggleCoreAsync(db,tx,dropOp);var removed=await ContentEditing.ReadAsync(db,tx,dropId);Assert((await ItemDropEditing.Capture(db,tx,copy.Id)).Tables["world_loot"].Count==0,"Undo removes boss-only assignment");await ContentEditing.ToggleCoreAsync(db,tx,removed);var bossSession=await ItemEditing.LoadAsync(copy.Id,db,tx);var changedLevel=new CatalogItem(new(bossSession.Current.Fields,StringComparer.OrdinalIgnoreCase){["ItemLevel"]="98"});await ItemEditing.SaveCoreAsync(db,tx,bossSession,changedLevel);var retained=(await WorldDrops.Capture(db,tx,new([copy.Id])))["world_drop_policy"].Single();Assert(JsonSerializer.Deserialize<DropPlan>(retained["PlanJson"]!)!.Mode=="Boss","Editing level retains explicit boss assignment, without world drops");
        }finally{await tx.RollbackAsync();}}finally{using var release=new MySqlCommand("SELECT RELEASE_LOCK('anocore_studio_forge')",db);await release.ExecuteScalarAsync();}
        Assert(HistoryActions.Canonical(initial)==HistoryActions.Canonical(await HistoryActions.CaptureAsync(db,null,19019)),"Thunderfury's current fields are left untouched");
        var locations=new DropLocationWindow(thunder.Current,world:world){Owner=this};locations.Show();await locations.Ready;locations.SelectBossForVerification(boss.Key);Assert(locations.Result?.Mode=="Boss","Boss selector UI builds boss-only plan");await RenderEditorWindow(locations,"instance-boss-drop-preview");locations.Close();
        await File.WriteAllTextAsync("artifacts/safety-stats-bosses-verification.json",JsonSerializer.Serialize(new{thunderfuryLevel=thunder.Current.ItemLevel,missingDamageRow=101,maximumInstalledDamageRow=100,mailAndShaman=true,intellectAndCritPersist=true,instances=world.Bosses.Select(b=>b.MapId).Distinct().Count(),bosses=world.Bosses.Count,sampleBoss=boss.Name,checks="Read-only crash/table diagnosis; missing-row save/copy/restore blocking; immediate stat-type edits persist through reload and undo/redo; named Mail filtering; Mail plus Shaman restrictions; boss-only assignment and history; explicit bosses retained on level change; all game test writes rolled back"},new JsonSerializerOptions{WriteIndented=true}));
    }
